WHERE user_id IN (
  'f5671ffe-f1b8-4e06-af75-1c739c3255e7',
  'dd1370e5-ce1f-437f-a554-96d186476489',
  '44eb4a19-defa-4fc4-8fd5-1cdf5b992170',
